package br.com.pelotavision;
import org.opencv.core.*;import org.opencv.imgproc.Imgproc;import org.opencv.imgcodecs.Imgcodecs;import java.nio.file.*;import java.util.*;import java.io.*;
public class RoiNative {
 static void check(boolean v,String message){if(!v)throw new AssertionError(message);}
 static String n(double d){return Double.isFinite(d)?Double.toString(d):"null";}
 public static void main(String[] args)throws Exception{
  nu.pattern.OpenCV.loadLocally();Core.setNumThreads(2);
  Mat full=new Mat(400,500,CvType.CV_8UC1,new Scalar(0));InterestRegion rect=new InterestRegion(InterestRegion.Shape.RECTANGLE,140,80,360,320);AnalysisWindow w=new AnalysisWindow(500,400,rect);
  for(int row=0;row<3;row++)for(int col=0;col<3;col++)Imgproc.circle(full,new Point(185+col*65,125+row*65),20+row,new Scalar(185+col*20),-1);
  Mat other=full.clone();byte[] bytes=new byte[500*400];other.get(0,0,bytes);for(int y=0;y<400;y++)for(int x=0;x<500;x++)if(!rect.contains(x+.5,y+.5))bytes[y*500+x]=(byte)255;other.put(0,0,bytes);
  Mat a=w.cropGray(full),b=w.cropGray(other);check(Core.norm(a,b,Core.NORM_INF)==0,"Outside pixels entered rectangular crop");
  DetectionTuner.Option option=new DetectionTuner.Option(3,75,false);DetectionAssessment.Context ctx=new DetectionAssessment.Context(null,500,400,null,5,w);
  DetectionTuner.Report first=DetectionTuner.search(a,option,ctx,()->false,(done,total,label)->{},120000),second=DetectionTuner.search(b,option,ctx,()->false,(done,total,label)->{},120000);check(first.trials.size()==24&&second.trials.size()==24,"Missing tested options");check(first.best().option.id.equals(second.best().option.id),"Outside light affected selected setting");
  for(DetectionTuner.Trial x:first.trials){DetectionTuner.Trial y=second.find(x.option.id);check(x.error==null&&y.error==null,"Candidate failed");check(x.result.circles.size()==y.result.circles.size(),"Outside light affected detection");check(Math.abs(x.score-y.score)<1e-9,"Outside light affected score");}
  System.out.println("PASS: 24 options, identical ROI pixels, segmentation and scores under opposite outside illumination.");
  AnalysisWindow circle=new AnalysisWindow(500,400,new InterestRegion(InterestRegion.Shape.CIRCLE,140,80,360,300));Mat ca=circle.cropGray(full);byte[] changed=bytes.clone();full.get(0,0,changed);for(int y=0;y<400;y++)for(int x=0;x<500;x++)if(!circle.region.contains(x+.5,y+.5))changed[y*500+x]=(byte)255;other.put(0,0,changed);Mat cb=circle.cropGray(other);check(Core.norm(ca,cb,Core.NORM_INF)==0,"Outside pixels entered circle or median");System.out.println("PASS: circle mask and fill median independent of outside pixels.");
  for(Mat m:Arrays.asList(full,other,a,b,ca,cb))m.release();
  Mat g=Imgcodecs.imread(args[0],0);AnalysisWindow real=new AnalysisWindow(g.cols(),g.rows(),new InterestRegion(InterestRegion.Shape.RECTANGLE,440,340,860,940));Mat crop=real.cropGray(g);
  DetectionTuner.Report report=DetectionTuner.search(crop,option,new DetectionAssessment.Context(null,g.cols(),g.rows(),null,5,real),()->false,(done,total,label)->System.out.println(done+"/"+total+" "+label));PelletDetector.Result local=report.best().result,result=real.toGlobal(local);CrackAnalysis cracks=real.toGlobal(new CrackDetector(new CrackModel(new FileInputStream(args[1]))).detect(crop,local,50));for(PelletDetector.Detection d:result.circles)check(real.region.includes(d),"Detection outside actual ROI");
  StringBuilder s=new StringBuilder("{\"width\":"+result.width+",\"height\":"+result.height+",\"crop_width\":"+real.width+",\"crop_height\":"+real.height+",\"method\":\""+result.method+"\",\"selected_option\":\""+report.best().option.id+"\",\"options\":"+report.trials.size()+",\"desktop_library\":\"OpenPnP OpenCV 4.9; Android uses 4.12\",\"physical_width_mm\":null,\"objects\":[");
  for(int i=0;i<result.circles.size();i++){PelletDetector.Detection d=result.circles.get(i);CrackAnalysis.Entry c=cracks.entries.get(i);if(i>0)s.append(',');s.append(String.format(Locale.ROOT,"{\"x\":%.8f,\"y\":%.8f,\"a\":%.8f,\"b\":%.8f,\"radius\":%.8f,\"angle\":%.8f,\"partial\":%s,\"review\":%s,\"fitted\":%s,\"support\":%s,\"rms\":%s,\"roundness\":%.8f,\"crack_x\":%.8f,\"crack_y\":%.8f,\"crack_radius\":%.8f,\"crack_review\":%s,\"crack_status\":\"%s\",\"crack_score\":%s,\"crack_runs\":[",d.x,d.y,d.semiMajor,d.semiMinor,d.radius,d.angleDeg,d.partial,d.needsReview,d.ellipseFitted,n(d.fitSupport),n(d.fitRms),d.roundness,d.crackX,d.crackY,d.crackRadius,d.crackNeedsReview,c.status,n(c.modelScore)));float[] runs=c.markedRuns();for(int k=0;k<runs.length;k++){if(k>0)s.append(',');s.append(runs[k]);}s.append("]}");}
  s.append("]}");Path path=Path.of(args[2]);Files.createDirectories(path.getParent());Files.writeString(path,s);System.out.println("PASS real ROI "+real.width+"x"+real.height+": "+result.circles.size()+" detections; "+report.best().option.id+"; "+report.durationMs+"ms. No known physical width; pixels only.");crop.release();g.release();
 }
}
